select jsonb_build_object('users',(select count(*)from auth.users where id::text like'fd240000-%'),'companies',(select count(*)from public.companies where id::text like'fd240000-%'),'deals',(select count(*)from public.deals where company_id::text like'fd240000-%'),'signings',(select count(*)from private.contract_signings where company_id::text like'fd240000-%'),'paymentEntries',(select count(*)from private.deal_payment_entries where company_id::text like'fd240000-%'),'deliveries',(select count(*)from private.deal_deliveries where company_id::text like'fd240000-%'),'requests',(select count(*)from private.deal_fulfilment_requests where company_id::text like'fd240000-%')) result;
